15 | /** Never part of a repository on GitHub, and huge when present locally. */
16 | const SKIP = new Set(['node_modules', '.git'])
17 | 
18 | /** Every file under `dir`, as forward-slash paths relative to it. */
19 | function walk(dir: string): string[] {
20 |   const out: string[] = []
21 |   const visit = (current: string) => {
22 |     for (const entry of readdirSync(current, { withFileTypes: true })) {
23 |       if (SKIP.has(entry.name)) continue
24 |       const full = join(current, entry.name)
25 |       if (entry.isDirectory()) visit(full)
26 |       else if (entry.isFile()) out.push(relative(dir, full).split(sep).join('/'))
27 |     }
28 |   }
29 |   visit(dir)
30 |   return out
31 | }
32 | 
33 | /** Links in a page, skipping fenced code, where a link is only an example. */
34 | function linksIn(content: string): string[] {
35 |   const links: string[] = []
36 |   let fenced = false
37 |   for (const line of content.split('\n')) {
38 |     if (/^\s*(```|~~~)/.test(line)) {
39 |       fenced = !fenced
40 |       continue
41 |     }
42 |     if (fenced) continue
43 |     for (const match of line.replace(/`[^`]*`/g, '').matchAll(/\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g)) {
44 |       links.push(match[1])
45 |     }
46 |   }
47 |   return links
48 | }
49 | 
50 | /**
51 |  * Checks a repository's docs the way DocuGate will read them, so problems turn
52 |  * up on the command line or in CI rather than on the published page.
53 |  *
54 |  * Errors are things DocuGate will get wrong or refuse. Warnings are things it
55 |  * handles, but probably not the way the author meant.
56 |  */
57 | export function check(root: string, dirOverride?: string): CheckResult {
58 |   const loaded = loadConfig(root)
59 |   const errors = [...loaded.errors]
60 |   const warnings = [...loaded.warnings]
61 |   const docsDir = (dirOverride ?? loaded.docsDir).replace(/^\/|\/$/g, '') || '.'
62 |   const base = docsDir === '.' ? root : join(root, docsDir)
63 | 
64 |   if (!existsSync(base) || !statSync(base).isDirectory()) {
65 |     errors.push({
66 |       message: `The docs folder "${docsDir}" does not exist.${
67 |         loaded.found ? '' : ' Set "docsDir" in docugate.json, or run `docugate init`.'
68 |       }`,
69 |     })
70 |     return { docsDir, pages: 0, errors, warnings }
71 |   }
72 | 
73 |   const files = walk(base)
74 |   const pages = files.filter((f) => /\.md$/i.test(f))
75 |   const shown = (p: string) => (docsDir === '.' ? p : `${docsDir}/${p}`)
76 | 
77 |   for (const f of files.filter((f) => /\.mdx$/i.test(f))) {
78 |     warnings.push({ file: shown(f), message: 'is MDX, which DocuGate does not read. Rename it to .md.' })
79 |   }
80 | 
81 |   if (pages.length === 0) {
82 |     errors.push({ message: `There are no .md files in "${docsDir}", so the space would be empty.` })
83 |     return { docsDir, pages: 0, errors, warnings }
84 |   }
85 |   if (pages.length > MAX_FILES) {
86 |     errors.push({
87 |       message: `"${docsDir}" has ${pages.length} markdown files. DocuGate refuses more than ${MAX_FILES}.`,
88 |     })
89 |   }
90 | 
91 |   // Two files that route to the same URL: only one of them can be reached.
92 |   const bySlug = new Map<string, string[]>()
93 |   for (const p of pages) bySlug.set(pathToSlug(p), [...(bySlug.get(pathToSlug(p)) ?? []), p])
94 |   for (const [slug, clash] of bySlug) {
95 |     if (clash.length > 1) {
96 |       errors.push({
97 |         message: `${clash.map(shown).join(' and ')} both become the page "/${slug}". Rename one.`,
98 |       })
99 |     }
100 |   }

